<?php
declare(strict_types=1);

final class Overview
{
    public function __construct(private PDO $db){}
    private function query(string $sql,array $args=[]):PDOStatement{$s=$this->db->prepare($sql);$s->execute($args);return $s;}
    public function get(array $input,?DateTimeImmutable $now=null):array
    {
        if(array_diff(array_keys($input),['queue','page'])||!in_array($input['queue'] ?? 'TODAY',['TODAY','TOMORROW','DUE','UNPAID','REQUESTED'],true)||isset($input['page'])&&(!is_string($input['page'])||!preg_match('/^[1-9][0-9]{0,6}$/D',$input['page'])||(int)$input['page']>1000000))throw new HttpError(400,'Bộ lọc tổng quan không hợp lệ.');$queue=$input['queue'] ?? 'TODAY';$now??=new DateTimeImmutable('now',new DateTimeZone('UTC'));$local=$now->setTimezone(new DateTimeZone('Asia/Ho_Chi_Minh'));$today=$local->format('Y-m-d');$tomorrow=$local->modify('+1 day')->format('Y-m-d');$start=$local->setTime(0,0)->setTimezone(new DateTimeZone('UTC'));$end=$start->modify('+1 day');
        $guests='(';for($i=0;$i<6;$i++)$guests.=($i?'+':'')."COALESCE(CAST(JSON_UNQUOTE(JSON_EXTRACT(o.snapshot,'$.lines[$i].quantity')) AS UNSIGNED),0)";$guests.=')';$date="JSON_UNQUOTE(JSON_EXTRACT(o.snapshot,'$.date'))";$due="o.booking_status='CONFIRMED' AND o.payment_status IN ('PAID','CREDIT') AND $guests>COALESCE(t.issued,0)";$source=" FROM jingo_orders o LEFT JOIN (SELECT order_id,SUM(covers) AS issued FROM jingo_order_tickets GROUP BY order_id) t ON t.order_id=o.id WHERE o.booking_status<>'CANCELLED' AND NOT EXISTS(SELECT 1 FROM jingo_order_archives a WHERE a.order_id=o.id)";
        $this->db->exec('SET TRANSACTION ISOLATION LEVEL REPEATABLE READ');$this->db->beginTransaction();try{
            $counts=$this->query("SELECT SUM(CASE WHEN $date=? THEN 1 ELSE 0 END) AS today,SUM(CASE WHEN $date=? THEN 1 ELSE 0 END) AS tomorrow,SUM(CASE WHEN $due THEN 1 ELSE 0 END) AS due,SUM(CASE WHEN o.payment_status='UNPAID' THEN 1 ELSE 0 END) AS unpaid,SUM(CASE WHEN o.booking_status='REQUESTED' THEN 1 ELSE 0 END) AS requested,SUM(CASE WHEN o.created_at>=? AND o.created_at<? THEN 1 ELSE 0 END) AS created".$source,[$today,$tomorrow,$start->format('Y-m-d H:i:s'),$end->format('Y-m-d H:i:s')])->fetch(PDO::FETCH_ASSOC);$counts=array_map(fn($v)=>(int)$v,$counts);$total=$counts[strtolower($queue)];$pages=max(1,(int)ceil($total/25));$page=min((int)($input['page'] ?? 1),$pages);$where=match($queue){'TODAY','TOMORROW'=>"$date=?",'DUE'=>$due,'UNPAID'=>"o.payment_status='UNPAID'",'REQUESTED'=>"o.booking_status='REQUESTED'"};$args=in_array($queue,['TODAY','TOMORROW'],true)?[$queue==='TODAY'?$today:$tomorrow]:[];
            $rows=$this->query("SELECT o.id,o.code,JSON_UNQUOTE(JSON_EXTRACT(o.snapshot,'$.productName')) AS product,JSON_UNQUOTE(JSON_EXTRACT(o.snapshot,'$.variantName')) AS variant,$date AS visit_date,JSON_UNQUOTE(JSON_EXTRACT(o.contact,'$.name')) AS customer,o.booking_status,o.payment_status,$guests AS guests,COALESCE(t.issued,0) AS issued".$source.' AND ('.$where.") ORDER BY $date,o.created_at,o.id LIMIT 25 OFFSET ".(($page-1)*25),$args)->fetchAll(PDO::FETCH_ASSOC);foreach($rows as &$row){$row['guests']=(int)$row['guests'];$row['issued']=(int)$row['issued'];$row['channel']='WEB';}unset($row);$contact=(int)$this->query("SELECT COUNT(*) FROM jingo_contact_requests WHERE status='NEW'")->fetchColumn();$this->db->commit();return ['date'=>$today,'tomorrow'=>$tomorrow,'updatedAt'=>$now->format('c'),'counts'=>$counts,'alerts'=>['contact'=>$contact],'queue'=>$queue,'data'=>$rows,'page'=>$page,'pages'=>$pages,'total'=>$total,'pageSize'=>25];
        }catch(Throwable $e){if($this->db->inTransaction())$this->db->rollBack();throw $e;}
    }
}
